function ws(){return state.workspace||{clients:[],followUps:[],threads:[],messages:[],gifts:[],referrals:[],events:[],fieldJobs:[],requests:[],plan:null,stats:{available:0,pending:0,sales:0}}}
function planRecord(){return ws().plan||{address:'',clientName:'',stage:'Under contract / due diligence',targetClose:'',realtorName:'',goal:'Buyer repair negotiation',status:'draft',pricing:'fixed',credit:0,selectedIds:[]}}
function planPayload(extra){const p=planRecord();return Object.assign({address:el('planAddress')?.value??p.address,clientName:el('planClient')?.value??p.clientName,stage:el('planStage')?.value??p.stage,targetClose:el('planClose')?.value??p.targetClose,realtorName:el('planRealtor')?.value??p.realtorName,goal:el('planGoal')?.value??p.goal,status:state.planStatus,pricing:state.planPricing,credit:state.planCredit,selectedIds:state.planSelected},extra||{})}
function applyWorkspace(data){state.workspace=data;const plan=data&&data.plan;if(!plan)return;state.planStatus=plan.status||'draft';state.planPricing=plan.pricing||'fixed';state.planCredit=Number(plan.credit)||0;if(Array.isArray(plan.selectedIds)&&plan.selectedIds.length)state.planSelected=plan.selectedIds}
async function refreshWorkspace(){const response=await fetch('/api/workspace');if(!response.ok)throw new Error('workspace');applyWorkspace(await response.json())}
async function saveWorkspace(url,method,body){const options={method,headers:{}};if(body!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}const response=await fetch(url,options);if(!response.ok)throw new Error('save');applyWorkspace(await response.json());render()}
