const pageHead=(ey,en,es,descEn,descEs,actions='')=>`<header class="page-head"><div><span class="eyebrow">${ey}</span><h1>${t(en,es)}</h1><p>${t(descEn,descEs)}</p></div><div class="page-actions">${actions}</div></header>`;

function applyLanguage(){
  document.documentElement.lang=state.lang;
  document.querySelectorAll('[data-i18n]').forEach(node=>{const pair=I18N[node.dataset.i18n];if(pair)node.textContent=pair[state.lang==='en'?0:1]});
  document.querySelectorAll('[data-placeholder-en]').forEach(node=>node.placeholder=state.lang==='en'?node.dataset.placeholderEn:node.dataset.placeholderEs);
  el('languageBtn').textContent=state.lang==='en'?'ES':'EN';
}
function navigate(route){
  if(route==='blueprint')route=state.loggedIn?'home':'welcome';
  if(!state.loggedIn&&!publicRoutes.has(route)){
    state.pendingRoute=route;
    openModal('loginModal');
    return;
  }
  if(route!==state.route)state.previousRoute=state.route;
  state.route=route;location.hash=route;
  document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route&&b.closest('.nav')));
  render();
  closeNavMenus();closeProfileMenu();
  el('main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});
}
function goBack(){
  if(state.route==='home'||state.route==='welcome')return;
  const fallback=state.loggedIn?'home':'welcome';
  const previous=state.previousRoute&&state.previousRoute!==state.route?state.previousRoute:fallback;
  navigate(state.loggedIn&&previous==='welcome'?'home':previous);
}
function toast(message){const box=el('toast');box.textContent=message;box.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.classList.remove('show'),2600)}
function persistEstimate(){localStorage.setItem('safe-estimate',JSON.stringify(state.estimate));updateCounts();renderDrawer()}
function updateCounts(){el('estimateCount').textContent=state.estimate.length;el('sideEstimateCount').textContent=state.estimate.length}
function openDrawer(){if(!state.loggedIn){state.pendingRoute='estimates';openModal('loginModal');return}renderDrawer();el('estimateDrawer').classList.add('open');el('estimateDrawer').setAttribute('aria-hidden','false');el('overlay').classList.add('open')}
function closeDrawer(){el('estimateDrawer').classList.remove('open');el('estimateDrawer').setAttribute('aria-hidden','true');el('overlay').classList.remove('open')}
function openModal(id){el(id).classList.add('open');if(id==='loginModal')showRealtorGate('choices')}
function closeModals(){document.querySelectorAll('.modal.open').forEach(m=>m.classList.remove('open'))}
function closeProfileMenu(){el('profileMenu')?.classList.remove('open');el('profileMenu')?.setAttribute('aria-hidden','true');el('profileBtn')?.setAttribute('aria-expanded','false')}
function closeNavMenus(){
  el('sidebar')?.classList.remove('open');
  el('publicMenu')?.classList.remove('open');
  el('publicMenu')?.setAttribute('aria-hidden','true');
  el('mobileMenu')?.setAttribute('aria-expanded','false');
  el('overlay')?.classList.remove('open');
}
function realtorAccounts(){try{return JSON.parse(localStorage.getItem('safe-realtor-accounts')||'[]')}catch{return[]}}
function saveRealtorAccounts(list){localStorage.setItem('safe-realtor-accounts',JSON.stringify(list))}
function readRealtorSession(){try{return JSON.parse(sessionStorage.getItem('safe-realtor-session')||'null')}catch{return null}}
function rememberRealtor(account){state.account=account;sessionStorage.setItem('safe-realtor-session',JSON.stringify(account));paintRealtor()}
function validEmail(value){return /^[^\s@]+@[^\s@]+\.[A-Za-z]{2,}$/.test(String(value||'').trim())}
function paintRealtor(){
  const account=state.account;if(!account)return;
  const mark=initials(account.name||'R')||'R';
  const firm=account.firm||'';
  [['profileInitial',mark],['menuInitial',mark],['partnerInitial',mark]].forEach(([id,value])=>{if(el(id))el(id).textContent=value});
  if(el('menuName'))el('menuName').textContent=account.name||'';
  if(el('menuFirm'))el('menuFirm').textContent=firm;
  if(el('partnerName'))el('partnerName').textContent=account.name||'';
  if(el('partnerFirm'))el('partnerFirm').textContent=firm;
}
function showRealtorGate(mode){
  state.loginMode=mode;
  const choices=el('realtorChoices'),create=el('realtorCreate'),sign=el('realtorSignIn'),form=el('loginForm'),title=el('loginTitle');
  if(!choices||!create||!sign)return;
  choices.hidden=mode!=='choices';
  form.hidden=mode==='choices';
  create.hidden=mode!=='create';
  sign.hidden=mode!=='signin';
  create.querySelectorAll('input,button').forEach(node=>{if(node.type!=='button')node.disabled=mode!=='create'});
  sign.querySelectorAll('input,button').forEach(node=>{if(node.type!=='button')node.disabled=mode!=='signin'});
  const key=mode==='create'?'createProfile':mode==='signin'?'signInExisting':'gateTitle';
  if(title&&I18N[key]){title.dataset.i18n=key;title.textContent=I18N[key][state.lang==='en'?0:1]}
}
function enterRealtor(account,message){
  rememberRealtor(account);
  state.loggedIn=true;
  closeModals();
  applyAccessMode();
  const target=state.pendingRoute||'home';
  state.pendingRoute=null;
  navigate(target);
  toast(message);
}
function applyAccessMode(){
  document.body.classList.toggle('public-mode',!state.loggedIn);
  document.querySelectorAll('.member-only').forEach(node=>node.hidden=!state.loggedIn);
  document.querySelectorAll('.guest-only').forEach(node=>node.hidden=state.loggedIn);
  if(state.loggedIn){el('publicMenu')?.classList.remove('open');paintRealtor()}
  if(!state.loggedIn&&state.route&&!publicRoutes.has(state.route)){
    state.pendingRoute=state.route;
    state.route='welcome';
  }
}
function repairRange(r){
  if(!Number.isFinite(Number(r.low)))return t('Consultation required','Requiere consulta');
  if(Number(r.low)===Number(r.high))return `${money(r.low)}${r.unit?' / '+r.unit:''}`;
  return `${money(r.low)}–${money(r.high)}`;
}
function addRepair(id){
  if(!state.loggedIn){state.pendingRoute='estimates';openModal('loginModal');return}
  const r=state.catalog.find(x=>x.id===id);if(!r)return;
  if(state.estimate.some(x=>x.id===id)){toast(t('Already in your estimate','Ya está en el estimado'));return}
  state.estimate.push({...r,qty:1});persistEstimate();toast(t('Repair added to estimate','Reparación agregada al estimado'));
}
function addBundle(id){
  if(!state.loggedIn){state.pendingRoute='estimates';openModal('loginModal');return}
  const bundle=allBundles.find(x=>x.id===id);if(!bundle)return;
  const current=new Set(state.estimate.map(x=>x.id));
  const additions=bundle.items.map(itemId=>state.catalog.find(x=>x.id===itemId)).filter(Boolean).filter(x=>!current.has(x.id));
  if(!additions.length){toast(t('This combo is already in your estimate','Este combo ya está en tu estimado'));return}
  state.estimate.push(...additions.map(x=>({...x,qty:1,bundle_id:bundle.id,bundle_version:'2026.10.04-02'})));
  persistEstimate();
  toast(t(`${additions.length} repairs added from ${bundle.name}`,`${additions.length} reparaciones agregadas de ${bundle.nameEs}`));
}
function removeRepair(id){state.estimate=state.estimate.filter(x=>x.id!==id);persistEstimate();if(state.route==='estimates')render()}
function renderDrawer(){
  const body=el('estimateItems');
  if(!state.estimate.length)body.innerHTML=`<div class="empty-state"><div class="empty-icon">▤</div><h3>${t('No repairs selected','No hay reparaciones')}</h3><p>${t('Search the catalog and add repairs to build an estimate.','Busca en el catálogo y agrega reparaciones.')}</p></div>`;
  else body.innerHTML=state.estimate.map(r=>`<div class="drawer-item"><div class="row"><strong>${esc(serviceName(r))}</strong><span class="price">${repairRange(r)}</span></div><small>${esc(state.lang==='en'?r.category:(categoryES[r.category]||r.category))}</small><br><button data-remove="${r.id}">${t('Remove','Quitar')}</button></div>`).join('');
  const low=state.estimate.reduce((s,r)=>s+(Number(r.low)||0),0),high=state.estimate.reduce((s,r)=>s+(Number(r.high)||Number(r.low)||0),0);
  el('estimateTotal').textContent=state.estimate.length?(low===high?money(low):`${money(low)}–${money(high)}`):'$0';
  body.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>removeRepair(b.dataset.remove));
}

