function universalResults(query){
  const q=normalized(query);if(!q)return[];
  const terms=q.split(/\s+/).filter(Boolean);
  const modules=moduleIndex.map(m=>{const hay=normalized(m.slice(2).join(' '));const score=terms.reduce((s,x)=>s+(hay.includes(x)?6:0),0);return score?{type:'module',route:m[0],icon:m[1],title:t(m[2],m[3]),subtitle:t('Tool or CRM section','Herramienta o sección CRM'),score}:null}).filter(Boolean);
  const repairs=searchCatalog(query).slice(0,8).map(r=>({type:'repair',route:'search',icon:'$',title:serviceName(r),subtitle:`${t('Repair','Reparación')} · ${repairRange(r)}`,repair:r,score:r.score+2}));
  const people=(ws().clients||[]).map(c=>{const hay=normalized([c.name,c.address,c.stageEn,c.stageEs].join(' '));const score=terms.reduce((s,x)=>s+(hay.includes(x)?5:0),0);return score?{type:'client',route:'clients',icon:initials(c.name),title:c.name,subtitle:c.address,score}:null}).filter(Boolean);
  const templates=monthlyTemplates.map(m=>{const hay=normalized([m.month,m.monthEs,m.title,m.titleEs,m.en,m.es].join(' '));const score=terms.reduce((s,x)=>s+(hay.includes(x)?4:0),0);return score?{type:'template',route:'campaigns',icon:'✦',title:t(m.title,m.titleEs),subtitle:t(m.month,m.monthEs),template:m,score}:null}).filter(Boolean);
  return [...modules,...repairs,...people,...templates].sort((a,b)=>b.score-a.score).slice(0,12);
}
function showGlobalResults(query){
  const box=el('globalResults'),results=universalResults(query);
  if(!query.trim()){box.classList.remove('open');box.innerHTML='';return}
  box.innerHTML=results.length?results.map((r,i)=>`<button class="global-result ${i===0?'active':''}" data-global-route="${r.route}" data-global-query="${r.type==='repair'?esc(query):''}" data-template="${r.template?.id||''}"><span class="result-icon">${esc(r.icon)}</span><span><strong>${esc(r.title)}</strong><small>${esc(r.subtitle)}</small></span><small>${r.type}</small></button>`).join(''):`<div class="global-empty">${t('No result yet. Try a client, repair, report, message or schedule.','Sin resultados. Busca un cliente, reparación, reporte, mensaje o agenda.')}</div>`;
  box.classList.add('open');
  box.querySelectorAll('[data-global-route]').forEach(b=>b.onclick=()=>{if(b.dataset.globalQuery)state.query=b.dataset.globalQuery;if(b.dataset.template)localStorage.setItem('safe-active-template',b.dataset.template);el('globalSearch').value='';box.classList.remove('open');navigate(b.dataset.globalRoute)});
}
function bundlePricing(bundle){
  const items=bundle.items.map(id=>state.catalog.find(x=>x.id===id)).filter(Boolean),separateLow=items.reduce((s,x)=>s+Number(x.low||0),0),separateHigh=items.reduce((s,x)=>s+Number(x.high||x.low||0),0),round5=n=>Math.round(n/5)*5;
  return {items,separateLow,separateHigh,groupedLow:round5(separateLow*(1-bundle.save[1]/100)),groupedHigh:round5(separateHigh*(1-bundle.save[0]/100))};
}
function bundleCard(bundle){
  const p=bundlePricing(bundle),added=p.items.length&&p.items.every(x=>state.estimate.some(y=>y.id===x.id));
  return `<article class="bundle-card"><header><div><span class="bundle-code">${bundle.id}</span><span class="tag ${bundle.accent}">${t(bundle.stage[0],bundle.stage[1])}</span></div><span class="save-badge">${t('SAVE','AHORRA')} ${bundle.save[0]}–${bundle.save[1]}%</span></header><h3>${t(bundle.name,bundle.nameEs)}</h3><p>${t(bundle.desc,bundle.descEs)}</p><div class="bundle-items">${p.items.map(x=>`<span>✓ ${esc(serviceName(x))}</span>`).join('')}</div><div class="bundle-price"><div><small>${t('Separate planning ranges','Rangos por separado')}</small><s>${money(p.separateLow)}–${money(p.separateHigh)}</s></div><div><small>${t('Grouped planning range','Rango agrupado')}</small><strong>${money(p.groupedLow)}–${money(p.groupedHigh)}</strong></div></div><button class="button ${added?'ghost':'primary'} wide" data-add-bundle="${bundle.id}">${added?t('Combo added ✓','Combo agregado ✓'):t(`Add ${p.items.length}-item combo`,`Agregar combo de ${p.items.length}`)}</button></article>`;
}
function libraryPatterns(){
  const categories=[...new Set(state.catalog.map(r=>r.category))];
  return `<section class="pattern-intro"><div><span class="eyebrow">${t('13 REPORTS REVIEWED','13 REPORTES REVISADOS')}</span><h2>${t('Recurring repair families found in real reports','Familias de reparación que se repiten en reportes reales')}</h2><p>${t('Every finding remains its own record, even when the client does not request a quote. This creates the permanent House Facts history.','Cada hallazgo queda como registro aunque el cliente no pida quote. Así se construye el historial permanente de House Facts.')}</p></div><span class="tag green">${state.catalog.length} ${t('matched scenarios','escenarios relacionados')}</span></section><div class="pattern-grid">${categories.map((category,i)=>{const items=state.catalog.filter(x=>x.category===category),sample=items.slice(0,4);return `<article class="pattern-card"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(state.lang==='en'?category:(categoryES[category]||category))}</h3><p>${sample.map(x=>esc(serviceName(x))).join(' · ')}</p><small>${items.length} ${t('repair scenarios','escenarios de reparación')}</small></div><button data-library-category="${esc(category)}">${t('Open category','Abrir categoría')}</button></article>`}).join('')}</div><div class="policy section-gap"><strong>${t('Coverage rule','Regla de cobertura')}:</strong> ${t('The library is extensible. An unmatched finding creates a pending catalog scenario for Management review; it is never discarded or forced into the wrong repair.','La librería es extensible. Un hallazgo sin coincidencia crea un escenario pendiente para revisión de Management; nunca se elimina ni se fuerza dentro de una reparación incorrecta.')}</div>`;
}
function paintLabel(value){
  const labels={'Best as add-on':'Mejor como add-on','One-painter task':'Trabajo de 1 pintor','One painter-day':'Día de 1 pintor','Two-painter task':'Trabajo de 2 pintores','Full-room package':'Paquete de cuarto','Detail work':'Trabajo de detalle','Source first':'Corregir fuente primero','Site visit':'Requiere visita','Measured scope':'Alcance medido','Add-on':'Add-on','Required verification':'Verificación requerida'};
  return state.lang==='es'?(labels[value]||value):value;
}
