  const overview=`<section class="library-overview"><div><span class="eyebrow">${t('REPAIR SCOPE LIBRARY','LIBRERÍA DE ALCANCES')}</span><strong>${t('Every finding has a place. Compatible work earns a better grouped range.','Cada hallazgo tiene su lugar. El trabajo compatible obtiene un mejor rango agrupado.')}</strong></div><div><span><b>${state.catalog.length}</b><small>${t('repair scenarios','escenarios')}</small></span><span><b>${categories.length}</b><small>${t('trade categories','categorías')}</small></span><span><b>${allBundles.length}</b><small>${t('smart combos','combos')}</small></span><span><b>13</b><small>${t('reports reviewed','reportes revisados')}</small></span></div></section>`;
  let content='';
