function selectedPlanFindings(){return repairPlanFindings.filter(x=>state.planSelected.includes(x.id))}
function planQty(id){return Math.max(1,Math.min(25,Number(state.planQuantities[id])||1))}
function findingLabel(x){return state.lang==='en'?x.finding:x.findingEs}
function planRollup(){
  const totals=selectedPlanFindings().reduce((a,x)=>{const qty=planQty(x.id);a.units+=qty;a.hoursMin+=x.hours[0]*qty;a.hoursMax+=x.hours[1]*qty;a.materialsMin+=x.materials[0]*qty;a.materialsMax+=x.materials[1]*qty;a.fixedMin+=x.fixed[0]*qty;a.fixedMax+=x.fixed[1]*qty;return a},{units:0,hoursMin:0,hoursMax:0,materialsMin:0,materialsMax:0,fixedMin:0,fixedMax:0});
  totals.hourlyMin=totals.hoursMin*state.planHourlyRate;totals.hourlyMax=totals.hoursMax*state.planHourlyRate;
  totals.hourlyProjectMin=totals.hourlyMin+totals.materialsMin;totals.hourlyProjectMax=totals.hourlyMax+totals.materialsMax;
  totals.fixedProjectMin=totals.fixedMin+totals.materialsMin;totals.fixedProjectMax=totals.fixedMax+totals.materialsMax;
  return totals;
}
function classCopy(code){
  const map={H1:[t('Handyman · predictable','Handyman · predecible'),'aqua'],H2:[t('Handyman · verify onsite','Handyman · verificar'),'gold'],T1:[t('Licensed trade','Especialidad licenciada'),'red'],Q1:[t('Custom quote required','Cotización requerida'),'navy']};
  return map[code]||map.H1;
}
