    <div class="plan-progress">${planSteps.map((s,i)=>`<button class="${state.planStep===i+1?'active':''} ${state.planStep>i+1?'done':''}" data-plan-step="${i+1}"><span>${state.planStep>i+1?'✓':i+1}</span><small>${t(s[0],s[1])}</small></button>`).join('')}</div>
