  if(state.planStep===2)return `<div class="plan-intro"><div><span class="eyebrow">${t('STEP 2 · INPUTS','PASO 2 · ENTRADAS')}</span><h2>${t('Add every source once','Agrega cada fuente una sola vez')}</h2><p>${t('The report, photos and manual notes stay attached to the same property.','El reporte, las fotos y notas quedan en la misma propiedad.')}</p></div><span class="data-object">inspection_report_id · asset_id</span></div><div class="source-grid"><label class="source-card selected"><input type="radio" name="planSource" checked><span>PDF</span><strong>${t('Inspection report','Reporte de inspección')}</strong><small>Smith_Home_Inspection.pdf · 86 pages</small></label><label class="source-card"><input type="radio" name="planSource"><span>▧</span><strong>${t('Property photos','Fotos de la propiedad')}</strong><small>${t('Add room and repair photos','Agrega fotos por área')}</small></label><label class="source-card"><input type="radio" name="planSource"><span>＋</span><strong>${t('Manual repair','Reparación manual')}</strong><small>${t('Add an item not in the report','Agrega un item fuera del reporte')}</small></label></div><label class="compact-upload"><input id="planReportFile" type="file" accept="application/pdf,image/*" multiple><span>＋</span><div><strong>${t('Add another report, photo or note','Agregar reporte, foto o nota')}</strong><small>${t('The preview keeps sample data; Óscar connects secure storage.','La vista conserva datos de muestra; Óscar conecta el almacenamiento seguro.')}</small></div></label>`;
